INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad viser den kolde krigs historiske forløb om forholdet mellem demokrati og fred — den såkaldte demokratiske fredsteori?","options":["Den kolde krig giver begrænset støtte: demokratier førte ikke storkrig mod hinanden men bekrigede aktivt ikke-demokratiske stater og støttede diktatorer der tjente geopolitiske interesser. Teorien er sandsynligvis sand for demokrati-par men understøtter ikke at demokratier altid fremmer fred generelt","Den kolde krig bekræfter fuldstændigt at demokratier aldrig fører krig og at demokratiudbredelse er den sikre vej til verdensfred","Den kolde krig afviser demokratisk fredsteori fordi USA og USSR aldrig kæmpede direkte mod hinanden","Demokratisk fredsteori er empirisk korrekt og det betyder at demokrati er det eneste politiske system der kan legitimt give mulighed for statsmæssig magtudøvelse"],"correct":"Den kolde krig giver begrænset støtte: demokratier førte ikke storkrig mod hinanden men bekrigede aktivt ikke-demokratiske stater og støttede diktatorer der tjente geopolitiske interesser. Teorien er sandsynligvis sand for demokrati-par men understøtter ikke at demokratier altid fremmer fred generelt","accepted_answers":["Den kolde krig giver begrænset støtte: demokratier førte ikke storkrig mod hinanden men bekrigede aktivt ikke-demokratiske stater og støttede diktatorer der tjente geopolitiske interesser. Teorien er sandsynligvis sand for demokrati-par men understøtter ikke at demokratier altid fremmer fred generelt"],"review_text":"Den demokratiske fredsteori (Kant, Doyle, Russett) påstår at liberale demokratier ikke fører krig mod hinanden — og den empiriske rekord er faktisk imponerende: ingen krig mellem etablerede liberale demokratier siden 1945. Men den kolde krig viser teoriens grænser: USA invaderede Grenada (1983), støttede Pinochets kup i Chile (1973), deltog i Koreakrigens massecivilbombing og i Vietnamkrigen. At demokratier er fredelige over for andre demokratier udelukker ikke aggressiv adfærd over for ikke-demokratier. Teorien beskriver et mønster der er statistisk solidt men politisk misbrugeligt som begrundelse for regimeskifte."}'::jsonb,
